import{_ as r,C as t,o,c as s,E as n,a2 as l}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/six-governance-20260918/when-rules-change-meaning.figure.en.svg",w=JSON.parse('{"title":"The rules are written. Why might an agent still make a different choice?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The rules are written. Why might an agent still make a different choice?","date":"2026-09-18","published_date":"2026-09-18","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The rules are written. Why might an agent still make a different choice?","summary":"An empty list of permitted directories returns allow. Three bounded experiments follow rule meaning through configuration, triggers and restored history.","cover":"/assets/six-governance-20260918/when-rules-change-meaning.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded original-code and public-artifact study; scope stated in text","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-09-18-when-rules-change-meaning.md","filePath":"en/research/2026-09-18-when-rules-change-meaning.md","lastUpdated":1789663032000}'),c={name:"en/research/2026-09-18-when-rules-change-meaning.md"};function h(p,e,u,m,g,f){const a=t("ArticleCover"),i=t("ArticleTableScroll");return o(),s("div",null,[n(a,{image:"/assets/six-governance-20260918/when-rules-change-meaning.cover-v1.png",kicker:"Open-source engineering · Experimental research",title:"The rules are written. Why might an agent still make a different choice?",summary:"An empty list of permitted directories returns allow. Three bounded experiments follow rule meaning through configuration, triggers and restored history.",version:"2026-09-18",languageHref:"/zh/research/2026-09-18-when-rules-change-meaning",languageLabel:"中文"}),n(i,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-rules-are-written-why-might-an-agent-still-make-a-different-choice" tabindex="-1">The rules are written. Why might an agent still make a different choice? <a class="header-anchor" href="#the-rules-are-written-why-might-an-agent-still-make-a-different-choice" aria-label="Permalink to &quot;The rules are written. Why might an agent still make a different choice?&quot;">​</a></h1><p>What does an empty list of permitted write directories mean?</p><p>A natural answer is “writes are forbidden everywhere.” The documentation example of one skill tool we studied gives that interpretation. Yet its original configuration loader and permission checker returned “allow.”</p><p>No business file was written in our experiment. The interesting discrepancy occurred earlier: the human-readable constraint and the computed decision already meant different things.</p><h2 id="following-principles-into-implementations" tabindex="-1">Following principles into implementations <a class="header-anchor" href="#following-principles-into-implementations" aria-label="Permalink to &quot;Following principles into implementations&quot;">​</a></h2><p><a href="https://arxiv.org/abs/2603.16586v1" target="_blank" rel="noreferrer">Runtime Governance</a>, by Maurits Kaptein and colleagues, emphasizes execution paths: earlier reads can change whether a later send is permissible. <a href="https://arxiv.org/abs/2503.18666v3" target="_blank" rel="noreferrer">AgentSpec</a>, by Haoyu Wang and colleagues, connects conditions to execution constraints. <a href="https://arxiv.org/abs/2512.03180v1" target="_blank" rel="noreferrer">AGENTSAFE</a>, co-authored by Mansura Habiba, brings capabilities, controls, oversight, and assurance evidence into a common framework.</p><p>We wanted to examine where these ideas require additional engineering evidence. We ran a public policy engine, a rule-trigger module, and a skill permission checker.</p><p>The provenance matters: we have not found an official AGENTSAFE implementation. Bulbasaur Skill CLI is a separate related project by Mansura. Its behavior is not an experimental validation of AGENTSAFE.</p><h2 id="two-meanings-of-an-empty-list" tabindex="-1">Two meanings of an empty list <a class="header-anchor" href="#two-meanings-of-an-empty-list" aria-label="Permalink to &quot;Two meanings of an empty list&quot;">​</a></h2><p>We loaded YAML through the original loader and submitted path strings to the original checker.</p><table tabindex="0"><thead><tr><th>Configuration and input</th><th>Checker decision</th></tr></thead><tbody><tr><td>Write rules omitted</td><td>Allow</td></tr><tr><td>Explicit <code>write_paths: []</code></td><td>Allow</td></tr><tr><td>Allow <code>/workspace/output/**</code>; path inside that directory</td><td>Allow</td></tr><tr><td>Same rule; path in another directory</td><td>Deny</td></tr><tr><td>Same rule; <code>/workspace/output/../other.txt</code></td><td>Allow</td></tr></tbody></table><p>The empty list means “no rules” to this evaluator, rather than “no permitted locations.” The last case shows that this method applies string glob matching without first resolving <code>..</code>.</p><p>This does not establish that a deployed runtime can write outside its authorized directory. Its caller might normalize paths or enforce an independent boundary. We verified the loader and evaluator, and a discrepancy with the documentation example.</p><p>All 29 selected upstream permission tests passed. One explicitly expects allowance when no filesystem rules exist. The tests verify an implementation choice. The remaining question is whether that choice matches the meaning presented to users.</p><h2 id="one-send-action-opposite-decisions" tabindex="-1">One send action, opposite decisions <a class="header-anchor" href="#one-send-action-opposite-decisions" aria-label="Permalink to &quot;One send action, opposite decisions&quot;">​</a></h2><p>Kyvvu’s public exfiltration policy provided a different controlled comparison. We held the send action constant and changed its recorded history.</p><p>A public-data read followed by a review record allowed the send. A sensitive-data read followed by the same review blocked it. Adding another review did not clear the restriction. Under this policy, sensitive access constrains subsequent actions throughout the task.</p><p>We then deliberately created a new engine with the same agent and task identifiers but supplied only the review record. The send was allowed. Restoring the sensitive-read history restored the block.</p><p><img src="'+d+'" alt="The same identifiers and action receive different decisions with full, partial and restored histories"></p><p><em>Figure 1. Changing the supplied history changes the send decision. Source: the tainted, fresh_engine_same_ids and restored_history cases in kyvvu-paths.json; decisions only, with no actual sends or claim of hosted recovery failure.</em></p><p>This is not a report of hosted-platform recovery failure. We intentionally withheld information the policy needs. The result demonstrates that <strong>identical identifiers cannot substitute for the history actually reaching the policy engine.</strong> Recovery and handoff mechanisms need to establish what governance history was restored, who supplied it, and how missing evidence is handled.</p><p>The eight selected upstream exfiltration tests also passed. Our six history controls evaluated decisions only; they did not send messages or transfer data.</p><h2 id="before-enforcement-the-rule-must-trigger" tabindex="-1">Before enforcement, the rule must trigger <a class="header-anchor" href="#before-enforcement-the-rule-must-trigger" aria-label="Permalink to &quot;Before enforcement, the rule must trigger&quot;">​</a></h2><p>AgentSpec directed our attention to an earlier boundary. We used its original parser to construct a PythonREPL rule and exercised the original trigger method.</p><p>An exact tool-name match triggered the rule. Renaming the tool prevented that match for the same text argument. A different tool could also trigger it when its text input began with PythonREPL.</p><p>Input types mattered too. An exact-name match with dictionary arguments returned true through short-circuit evaluation. A different name with dictionary arguments reached string handling and raised AttributeError. A finish action with None produced the same exception type.</p><p>We did not run the complete AgentExecutor, so these results do not establish that every integration fails. They identify an input-contract question: does the adapter supply strings, dictionaries, or null values? Does that contract survive tool wrapping and renaming?</p><p>A detailed safety condition cannot work as intended if its trigger receives an object outside the expected contract.</p><h2 id="from-having-rules-to-enforcing-their-meaning" tabindex="-1">From having rules to enforcing their meaning <a class="header-anchor" href="#from-having-rules-to-enforcing-their-meaning" aria-label="Permalink to &quot;From having rules to enforcing their meaning&quot;">​</a></h2><p>These experiments address distinct boundaries: configuration interpretation, action recognition, available history, and the eventual consumer of a decision. A single “governance enabled” indicator cannot establish them all.</p><p>Three small sets of checks are useful:</p><ol><li>Distinguish omitted settings, explicit empty values, and deny-all semantics. Compare documentation with tests.</li><li>Test actual tool names and argument types at the trigger boundary, including adapter transformations.</li><li>Verify that required history is present after recovery or handoff, and that a denial actually prevents the tool effect.</li></ol><p>That final effect-boundary check requires an execution experiment. Our evaluator controls cannot answer it.</p><p>For practitioners, a further question is whether agent handoffs should carry complete traces or a verifiable, sufficiently conservative governance state. For users, a simpler question is equally useful: when an interface says that no directories have been authorized, do you expect every write to be denied? That expectation should inform a contract test.</p><p>Governance needs clear constraints and evidence that their meaning survives implementation.</p><p>Study date: 17 September 2026. See the <a href="https://github.com/joinwell52-AI/joinwell52/blob/d258d0b925af198f0920fc6e897c390e02979900/research/manual-runs/2026-09-17-six-governance/00-report.md" target="_blank" rel="noreferrer">experiment report</a> for pinned commits, kyvvu-engine 0.11.0, controls, and limitations. These local experiments do not reproduce full paper evaluations, demonstrate a deployed escape, or establish a CodeFlowMu defect.</p><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',37))])}const v=r(c,[["render",h]]);export{w as __pageData,v as default};
